+// clockwise from the top edge, matching how a browser renders `<rect rx>`, so it composes with
+// `drawSvgPath`'s own Y-flip the same way the railroad's own `<path>` tracks already do.
+function roundedRectPath(
+  x: number,
+  y: number,
+  w: number,
+  h: number,
+  r: number,
